'use strict'

// Companion to 20260814020000-live-classes.js - seeds LiveClassAttendee
// from the same "Zetamari Students - Attendance" sheet's rows.
// liveClassId matches that seeder's per-date grouping; customerId matches
// 20260814000000-customers.js's row order. Must run after both.
//
// Rows with neither a name nor an email (blank/reserved seats the sheet
// keeps for future bookings) are skipped entirely - there's no identity
// to seed an attendee row from.
//
// Name parsing: the sheet's first column is "Last, First" per Angie's
// note, with an occasional trailing "(...)" annotation - e.g.
// "(cancelled)", "(friend)", "(Vivian's Sister)". The annotation is
// stripped from the name and, when not a cancellation marker, folded
// into notes as "From source sheet: ...". Names with no comma (a small
// handful of rows) are split on the first space instead.
//
// status: 'cancelled' when the name's annotation or the Upgrade
// Notes/Other Notes columns mention "cancel" in any form (matches "so
// marked in the first column" plus a couple of cases only marked in Other
// Notes); otherwise 'completed' for classes before today's seed date and
// 'enrolled' for classes still upcoming.
//
// discountPercent: only set where the sheet gives real evidence of one -
// an explicit "N% ... discount" mention in Other Notes wins outright;
// failing that, the sheet's own "Repeat" column (this student's Nth
// class) is used to infer the standard discount once it reaches 4, the
// same DISCOUNT_CLASS_COUNT/DEFAULT_DISCOUNT_PERCENT threshold
// libs/customerLoyalty.js already applies live - and a pattern the sheet
// itself confirms, since its explicit discount notes only ever start
// appearing at Repeat 4 or later for the students who have them. Rows
// with Repeat under 4 and no explicit note are left with no
// discountPercent rather than guessing.
//
// upgradeNotes maps directly from the sheet's own "Upgrade Notes" column,
// including plain "TBD" placeholders (kept verbatim - it's a real,
// intentional note, not blank data).
//
// notes carries forward everything else that doesn't have a column of
// its own: the non-cancellation annotation, the full Other Notes text
// (even when a discount percentage was parsed out of it), the "Special"
// column, an "Imported payment info: ..." summary of Paid 1/2, Class
// Cost, Up/AlC, and Balance (kept as the sheet's own values, including
// occasional non-numeric entries like "TRADE" or "Not Paid" verbatim, and
// literal "0" entries where that's what the sheet actually recorded), and
// the sheet's own Repeat count for reference.
//
// enrolledOn uses the sheet's Paid 1 Date as the best available proxy for
// when the student signed up, falling back to the Class Date itself when
// no payment date is present - not today's seed-run date, which would
// misrepresent nearly two decades of historical enrollments.
//
// Of the 1,601 seeded rows, 1,465 matched an existing Customer by email
// (a handful of shared-email cases were disambiguated using this row's
// own name against the candidates); the remaining rows are seeded with
// no customerId, per LiveClassAttendee's own design - a seat need not
// belong to a Customer record (walk-in guests, a plus-one, or simply
// someone who isn't in the customer master list export this was matched
// against).
